def extend(styles, families):
 notes='Estudo estático IA, não evidência de execução, produto real ou resultado. Movimento e áudio serão demonstrados na prévia de 10 segundos.'
 for family,raw in DATA.items():
  rows=[line.split('|') for line in raw.strip().splitlines()];assert len(rows)==8
  idx=next(i for i,f in enumerate(families) if f[0]==family);fid,title,kind,oldrows=families[idx];families[idx]=(fid,title,kind,oldrows+rows)
  for i,(name,signature,topic,uses,resources,motion) in enumerate(rows):
   slug=''.join(c for c in unicodedata.normalize('NFKD',name.lower()) if not unicodedata.combining(c));slug='-'.join(slug.split())
   v,m,s=FAMILY_AUDIO[family];audio=dict(voice=v,music=m,sfx=s,mix=AUDIO)
   rule=PROPERTY_LOCK if family=='imoveis' else SOFTWARE_LOCK if family=='software' else PRESENTATION_RULE if family=='apresentacoes' else LOCK if family in ['anuncios','campanhas'] else 'Distinguir metáforas e exemplos fictícios de fatos. Preservar referências e não prometer técnica que não será executada. Sem tremor contínuo; revisão em movimento e escuta.'
   requirement=rule
   if family=='tecnologia':requirement+=' Dados, eixos, escala, período, unidade e fonte precisam ser verificados; amostra ilustrativa não é análise real.'
   if family=='anuncios':requirement+=' Produto original protegido; vistas, testes e interior exigem evidência real. Não inventar variantes, atributos, acessórios ou resultados.'
   if family=='apresentacoes':requirement+=' Tipografia escolhida no briefing; confirmar licença e acentos. Mensagem final como texto editável.'
   styles.append(dict(id=slug,name=name,family=family,familyName=title,kind=kind,signature=signature,exampleTopic=topic,uses=uses,resources=resources.split('; '),motion=motion,complexity='Alta',note=('Interface demonstrativa construída em código; não é captura oficial. Dados fictícios e ações não executadas em plataforma real.' if family=='software' else notes),audio=audio,requirements=requirement,image=dict(atlas=f'assets/{family}-extra.webp',column=i%4,row=i//4,columns=4,rows=3,source='Interface demonstrativa em código' if family=='software' else 'Estudo visual IA'),preset=dict(version=3,skill='video-multimarcas',firstDelivery=['roteiro','storyboard visual','vídeo de 10 segundos para aprovação'],avatar=False,approvalGate='Aprovar os 10 segundos antes do vídeo completo.',productFidelity=rule,requiredAssets=requirement,research='Pesquisar fontes oficiais e primárias. Não apresentar exemplos como fatos.',quality='Provar a direção no plano mais exigente, com voz, som, ação interna e revisão audiovisual.')))
